### Lógica Principal (JavaScript)
Finalmente, implementamos a lógica principal utilizando JavaScript. Este script irá controlar a exibição dos painéis, realizar cálculos e validar entradas:

```javascript
// scripts.js
document.addEventListener('DOMContentLoaded', function () {

    const valueInput = document.getElementById("value");
    const pixButton = document.querySelector("#pix-panel button");
    const creditCardButton = document.querySelector("#credit-card-panel button");

    // Exibe/Esconde Panels
    function showPIXPanel(){
        hidePanels();
        document.getElementById("pix-panel").style.display = "block";
    }

    function hidePanels(){
        ["pix-panel", "credit-card-panel"].forEach(id => document.getElementById(id)?.style?.display = "none")
    }

    // Validations
    valueInput.addEventListener("blur", validateForm);

    function validateForm(event){
      if (!this.value || parseFloat(this.value) <= 0) {
          alert("Por favor, insira um valor válido.");
          this.focus();
          return false;
       } else if (/^[0-9]+(\.[^\d]*[\d]+\)$/.test(this.value)) this.step = 1;
     }

   // Métodos de Pagamento Selecionados
   pixButton.onclick = showPIXPanel;
   creditCardButton.onclick = showCCPanel;

   let selectedMethod = '';
   function changePaymentMethod(methodId){
      selectedMethod = methodId;
      switch(selectedMethod){
         case '': case 'pix':
             showPIXPanel(); break;
           default:
              showCCPanel();break;
      };
   };

   window.onload = function(){changePaymentMethod(localStorage.getItem('selected_method') ?? '')};

   // Cálculo de Parceleiros & Totals
   ['1', '2', '3'].map(n=>`${n}`).concat(['4', '5']).forEach((numStr,i)=>{
      setTimeout(()=>{
          document.getElementById(`option_${i+1}`).innerText=`(${Math.floor(((parseFloat(numStr)*10)+1)*10)/10}%) ${numStr} paras.`;
      }, i===0?0:500+(i-1)*(600));
   });

   document.getElementById("installments").onslectchanged=(evt)=>{calculateInstallmentValues(evt)}

   function calculateInstallmentValues(eventObj){
      const amountElement = document.getElementById("amount"),
            installmentSelect = eventObj.target,
            optionsArray=[...document.querySelectorAll('#installments > option')]
                  .filter(opt=> opt.nodeType===3 && !/\([\-\d]%\)\s*/.exec(opt.textContent)),
            indexOfSelectedOption = optionsArray.findIndex(x=> x==installmentSelect),
            ratePercentage=-indexOfSelectedOption/(optionsArray.length-1), // Linear interpolation between 0% upto highest one minus percentages
            finalPrice=parseFloat(valueInput.value)-(ratePercentage*(1-(parseFloat(valueInput.value))/100))*parseFloat(valueInput.value),
            singleMonthlyFee=Math.round(finalPrice/installmentSelect.value)+(ratePercentage&&((parseFloat(valueInput.value))/100)**(-1)));

      amountElement.innerText=${singleMonthlyFee.toString().replace('.','.')}.toLocaleString('en-US');
      document.getElementById("totalAmount").innerText="${"".padStart(2,' ')+0}${finalPrice.toFixed(2)}";

      storageLocalSetItem('lastCalculatedRatePerCent', `${ratePercentage * 100 | 0}`);
   };

   function payNow(){
      alert(`Sucesso!\nVocê pagou R$${valueInput.value}\npelo método "${selectedMethod}"`);
   };

});
```
